-- public.perform_telestone(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.perform_telestone(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare v_bx double precision; v_by double precision; v_bl int; v_why text; w world; v_ql double precision; s record; v_lx int; v_ly int; v_rest double precision; v_until timestamptz;
begin
  v_why := telestone_refusal(p_world, p_uid, p_action, p_target);
  if v_why is not null then
    perform tell(p_world, p_uid, v_why, 'error');
    return;
  end if;
  if p_target->>'stone' = 'back' then
    select l.x, l.y, l.level into v_bx, v_by, v_bl from telestone_back_landing(p_world, p_uid) l;
    update player set x = v_bx, y = v_by, level = v_bl, moved_at = now(), seen_at = now(), away = false
     where world_id = p_world and uid = p_uid;
    delete from telestone_back where world_id = p_world and uid = p_uid;
    perform tell(p_world, p_uid, 'Travelled back to where you left from.', 'event');
    if private.here(p_world, p_uid) then
      perform private.send('own:' || p_world || ':' || p_uid, 'moved',
        jsonb_build_object('x', v_bx, 'y', v_by, 'level', v_bl, 'back', null));
    end if;
    return;
  end if;
  select * into w from world where id = p_world;
  select i.ql into v_ql from item i where i.id = target_item(p_target) and i.world_id = p_world;
  select c.* into s from runestone_centres(w.size) c where c.id = p_target->>'stone';
  select l.x, l.y into v_lx, v_ly from telestone_landing(p_world, s.id) l;
  v_rest := telestone_rest(v_ql);
  v_until := now() + make_interval(secs => v_rest);
  insert into telestone_back (world_id, uid, x, y, level)
    select p_world, p_uid, q.x, q.y, q.level from player q where q.world_id = p_world and q.uid = p_uid
    on conflict (world_id, uid) do update set x = excluded.x, y = excluded.y, level = excluded.level;
  update player set x = v_lx + 0.5, y = v_ly + 0.5, level = 0, moved_at = now(), seen_at = now(), away = false
   where world_id = p_world and uid = p_uid;
  perform journal_note(p_world, p_uid, 'telestone');
  perform journal_note(p_world, p_uid, 'stone:' || s.id);
  insert into telestone_journey (world_id, uid, used_at, until) values (p_world, p_uid, now(), v_until)
    on conflict (world_id, uid) do update set used_at = excluded.used_at, until = excluded.until;
  perform tell(p_world, p_uid, 'Travelled to ' || s.name
    || '. Telestone cooldown: ' || time_words(v_rest) || '.', 'event');
  if private.here(p_world, p_uid) then
    perform private.send('own:' || p_world || ':' || p_uid, 'moved',
      jsonb_build_object('x', v_lx + 0.5, 'y', v_ly + 0.5, 'level', 0, 'until', extract(epoch from v_until)::double precision,
                         'back', (select jsonb_build_object('x', k.x, 'y', k.y, 'level', k.level) from telestone_back k
                                   where k.world_id = p_world and k.uid = p_uid)));
  end if;
end $function$
